pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bool willRevert) public {
        amount = bound(amount, 0, 1 ether);

        ReverterOrAcceptor helper = new ReverterOrAcceptor(willRevert);

        vm.deal(address(c), 1 ether);

        bool ok;
        try c.sendMoney(address(helper), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract ReverterOrAcceptor {
    bool public doRevert;
    constructor(bool _doRevert) payable {
        doRevert = _doRevert;
    }
    fallback() external payable {
        if (doRevert) revert("revert on purpose");
    }
}
